  /* ---------- bar chart (single series, hover tooltips) ---------- */
  function barChart(points, unit) {
    if (!points.length) return '<p class="muted">–</p>';
    const W = 560, H = 220, L = 52, B = 30, T0 = 14;
    const max = Math.max(...points.map(p => p.v), 0) * 1.15 || 1, min = Math.min(0, ...points.map(p => p.v));
    const y = v => T0 + (H - T0 - B) * (1 - (v - min) / (max - min));
    const step = (W - L - 10) / points.length, bw = Math.min(56, step * 0.6);
    let s = `<svg viewBox="0 0 ${W} ${H}" role="img">`;
    [0, .25, .5, .75, 1].map(f => min + (max - min) * f).forEach(v => {
      s += `<line class="ax" x1="${L}" x2="${W - 6}" y1="${y(v)}" y2="${y(v)}"/><text x="${L - 6}" y="${y(v) + 4}" text-anchor="end">${fmt(+v.toFixed(v >= 100 ? 0 : 1), unit)}</text>`;
    });
    points.forEach((p, i) => {
      const x = L + step * i + (step - bw) / 2, top = y(Math.max(0, p.v)), h = Math.abs(y(p.v) - y(0)), r = Math.min(4, bw / 2, h);
      const tip = `${p.label}: ${fmt(p.v, unit)} ${unitLbl(unit)}${p.src ? " · " + p.src : ""}`;
      s += p.v >= 0 ? `<path class="bar" d="M${x},${top + h} V${top + r} Q${x},${top} ${x + r},${top} H${x + bw - r} Q${x + bw},${top} ${x + bw},${top + r} V${top + h} Z"/>`
        : `<rect class="bar" x="${x}" y="${y(0)}" width="${bw}" height="${h}"/>`;
      s += `<rect x="${L + step * i}" y="${T0}" width="${step}" height="${H - T0 - B}" fill="transparent" data-tip="${esc(tip)}"/>`;
      s += `<text x="${x + bw / 2}" y="${H - 10}" text-anchor="middle">${esc(p.label)}</text>`;
    });
    return s + "</svg>";
  }
